/// # Safety
/// The all-zero bit pattern must be a valid Self value.
unsafe trait ZeroIsValid {}

#[repr(transparent)]
struct Byte(u8);
// SAFETY: every u8 bit pattern is valid, including zero.
unsafe impl ZeroIsValid for Byte {}

